previewCss:
.darma-loader-darma-b14-shell-game { --accent: var(--loader-color, #b91c1c); --accent-2: var(--loader-secondary-color, #78350f); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .52); position: relative; }
.darma-loader-darma-b14-shell-game::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 6%; border-radius: 999px; background: color-mix(in srgb, #000 24%, var(--accent-2)); }
.darma-loader-darma-b14-shell-game span { position: absolute; bottom: 6%; width: 26%; height: 74%; border-radius: 42% 42% 6px 6px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); box-shadow: inset calc(var(--loader-size, 120px) * .02) 0 calc(var(--loader-size, 120px) * .03) rgba(255, 255, 255, .2); }
.darma-loader-darma-b14-shell-game span:nth-child(1) { left: 4%; animation: darma-loader-darma-b14-shell-game-swap-right calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b14-shell-game span:nth-child(2) { left: 37%; animation: darma-loader-darma-b14-shell-game-cup-bob calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b14-shell-game span:nth-child(3) { left: 70%; animation: darma-loader-darma-b14-shell-game-swap-left calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-shell-game-swap-right { 0%, 10% { transform: translate(0, 0); } 34% { transform: translate(127%, -24%); } 50%, 62% { transform: translate(254%, 0); } 86% { transform: translate(127%, -24%); } 100% { transform: translate(0, 0); } }
@keyframes darma-loader-darma-b14-shell-game-swap-left { 0%, 10% { transform: translate(0, 0); } 34% { transform: translate(-127%, 24%); } 50%, 62% { transform: translate(-254%, 0); } 86% { transform: translate(-127%, 24%); } 100% { transform: translate(0, 0); } }
@keyframes darma-loader-darma-b14-shell-game-cup-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-12%); } }

